'use strict';
// Example CORTEX module — stands in for a real RL self-play loop. Appends one "round"
// to the ledger so `cortex run` can health-gate it. Replace with your own learner.
const fs = require('fs'), path = require('path');
const LEDGER = path.join(__dirname, '.cortex', 'self-play.jsonl');
fs.mkdirSync(path.dirname(LEDGER), { recursive: true });
let prev = 0;
try { const l = fs.readFileSync(LEDGER, 'utf8').trim().split('\n').filter(Boolean); if (l.length) prev = JSON.parse(l[l.length - 1]).episodes_total || 0; } catch (_) {}
const line = { ts: new Date().toISOString(), episodes_total: prev + 9, avg_best_light: 0.9 + Math.min(0.09, prev / 1000) };
fs.appendFileSync(LEDGER, JSON.stringify(line) + '\n');
console.log('self-play round: episodes_total', line.episodes_total, 'reward', line.avg_best_light.toFixed(3));

'use strict';
// Example CORTEX module — stands in for a recursive-learning cycle. Appends one cycle
// so `cortex run` sees the ledger grow. Replace with your own learner.
const fs = require('fs'), path = require('path');
const LEDGER = path.join(__dirname, '.cortex', 'recursive-learn.jsonl');
fs.mkdirSync(path.dirname(LEDGER), { recursive: true });
const line = { ts: new Date().toISOString(), cycle: 'demo', signals: 3, surprises: 1, learning: 'example insight' };
fs.appendFileSync(LEDGER, JSON.stringify(line) + '\n');
console.log('recursive-learn cycle appended');
